// generate-preset-bundle.mjs
//
// WHY THIS EXISTS
// ---------------
// qq-bridge ships its agent presets in the LEGACY user-preset layout:
//     $DSH_HOME/.agent-presets/<id>/{preset.yml, agent.cordis.yml, qq-tool-restrict.mjs}
// That layout was removed in DSH 0.1.7: nothing reads that directory any more, so
// `session.create` with agentPreset=qq-chat fails with
//     agent-preset/not-found: Unknown agent preset: qq-chat
// The bridge then refuses to build any session (resolvePresetName uses strict:true and
// must not fall back to the default preset, which carries local tools).
//
// DSH 0.1.7 presets are ordinary `@deepseek-ai/dsh-agent-preset` declarations carried by a
// bundle patch. This script converts the legacy directories into that format:
//     preset.yml        -> config.name / config.description / config.order
//     agent.cordis.yml  -> config.plugins (verbatim plugin entry list)
// and copies qq-tool-restrict.mjs next to the patch, because the preset's relative plugin
// "./qq-tool-restrict.mjs" resolves against the declaring bundle's directory.
//
// Run:  node dsh/generate-preset-bundle.mjs
// Output: dsh/preset-bundle/cordis.patch.yml   (plus qq-tool-restrict.mjs)
//
// Re-run it whenever dsh/agent-presets/* changes. The plugin entry lists are passed
// through untouched -- only their YAML serialization is regenerated.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import yaml from 'js-yaml';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const PRESET_ROOT = path.join(HERE, 'agent-presets');
const BUNDLE_DIR = path.join(HERE, 'preset-bundle');

// Display order: keep the legacy numbers so the roster position is unchanged.
const PRESETS = ['qq-chat', 'qq-chat-v2'];

const header = `# GENERATED by dsh/generate-preset-bundle.mjs -- do not edit by hand.
#
# DSH 0.1.7 agent-preset declarations for qq-bridge, migrated from the legacy
# $DSH_HOME/.agent-presets/<id>/ directory layout (removed in 0.1.7, see
# @deepseek-ai/dsh-agent-preset/skills/editing-cordis-compositions/SKILL.md).
#
# Each row declares one preset; config.plugins is the legacy agent.cordis.yml entry list
# verbatim. The preset's relative plugin "./qq-tool-restrict.mjs" resolves against this
# bundle's directory, so that file must sit next to this patch file.
`;

const sections = [];
for (const id of PRESETS) {
  const dir = path.join(PRESET_ROOT, id);
  const presetYml = path.join(dir, 'preset.yml');
  const cordisYml = path.join(dir, 'agent.cordis.yml');

  for (const file of [presetYml, cordisYml]) {
    if (!fs.existsSync(file)) throw new Error(`missing preset source: ${file}`);
  }

  const meta = yaml.load(fs.readFileSync(presetYml, 'utf8')) ?? {};
  const plugins = yaml.load(fs.readFileSync(cordisYml, 'utf8'));
  if (!Array.isArray(plugins) || plugins.length === 0) {
    throw new Error(`${cordisYml} must contain a non-empty plugin entry list`);
  }

  // The declaration config, field order mirroring the documented format.
  const config = { id };
  if (meta.name !== undefined) config.name = meta.name;
  if (meta.description !== undefined) config.description = meta.description;
  if (meta.order !== undefined) config.order = meta.order;
  config.plugins = plugins;

  const row = [{ insert: [{ id: `preset-${id}`, name: '@deepseek-ai/dsh-agent-preset', config }] }];
  const body = yaml.dump(row, { lineWidth: -1, noRefs: true, quotingType: '"', forceQuotes: false });

  const relative = plugins.filter((p) => typeof p?.name === 'string' && p.name.startsWith('./')).map((p) => p.name);
  sections.push(`# ---- preset: ${id} (${plugins.length} plugin entries${relative.length ? `, relative: ${relative.join(', ')}` : ''}) ----`);
  sections.push(body.trimEnd());
  console.log(`[preset] ${id}: ${plugins.length} plugin entries, order=${meta.order ?? '(none)'}, name=${JSON.stringify(meta.name ?? null)}`);
  for (const rel of relative) console.log(`         relative plugin -> ${rel} (resolved against the bundle dir)`);
}

const out = `${header}\n${sections.join('\n\n')}\n`;
fs.mkdirSync(BUNDLE_DIR, { recursive: true });
const target = path.join(BUNDLE_DIR, 'cordis.patch.yml');
fs.writeFileSync(target, out, 'utf8');
console.log(`\nwrote ${target} (${out.length} bytes)`);

// Keep a real copy of the relative plugin beside the patch: the loader resolves
// "./qq-tool-restrict.mjs" against the DECLARING patch file's directory. The declarations
// are appended to the PROFILE's cordis.patch.yml, and the loader imports a patch row with
// the baseUrl of the file that declared it (see dsh-app-boot: `ctx.baseUrl =
// pathToFileURL(dirname(absoluteConfigPath))`, then `loader.import(row.name, baseUrl)`).
// So the safety plugin must exist next to the profile patch file, not only in this bundle.
const restrictSrc = path.join(PRESET_ROOT, 'qq-chat', 'qq-tool-restrict.mjs');
const restrictDst = path.join(BUNDLE_DIR, 'qq-tool-restrict.mjs');
fs.copyFileSync(restrictSrc, restrictDst);
console.log(`copied ${path.basename(restrictDst)} -> ${restrictDst}`);

// Second copy, resolved against the profile patch file. Keep it here too so the bundle is
// self-contained for other machines that install it as a real bundle.
const dshHome = process.env.DSH_HOME || path.join(process.env.USERPROFILE ?? process.env.HOME ?? '', '.dsh');
const profilePatchDir = path.join(dshHome, 'profiles', 'web');
if (fs.existsSync(profilePatchDir)) {
  const profileCopy = path.join(profilePatchDir, 'qq-tool-restrict.mjs');
  fs.copyFileSync(restrictSrc, profileCopy);
  console.log(`copied ${path.basename(profileCopy)} -> ${profileCopy}  (profile patch baseUrl)`);
} else {
  console.log(`[warn] profile dir not found, skipped the profile-side copy: ${profilePatchDir}`);
  console.log('       run install-preset-bundle.ps1 (it also places this file) if DSH lives elsewhere.');
}

// Sanity: the file we just wrote must parse back to the same plugin lists.
const reparsed = yaml.load(fs.readFileSync(target, 'utf8'));
for (const op of reparsed) {
  const decl = op?.insert?.[0];
  const src = yaml.load(fs.readFileSync(path.join(PRESET_ROOT, decl.config.id, 'agent.cordis.yml'), 'utf8'));
  if (JSON.stringify(decl.config.plugins) !== JSON.stringify(src)) {
    throw new Error(`round-trip mismatch for preset ${decl.config.id}`);
  }
}
console.log('round-trip verified: every plugin list survives YAML serialization unchanged');
